function updateNotificationBadgeCount() {
  const unread = notificationList.querySelectorAll(".notification-item.unread").length;
  if (unread > 0) {
    notificationBadgeCount.textContent = unread > 99 ? "99+" : String(unread);
    notificationBadgeCount.removeAttribute("hidden");
  } else {
    notificationBadgeCount.setAttribute("hidden", "");
  }
}

function setNotificationPanelOpen(open) {
  notificationCenterPanel.hidden = !open;
  notificationCenterToggle.setAttribute("aria-expanded", open ? "true" : "false");
