let notificationDynamicSeq = 3000;

function pushAppNotification(title, meta) {
  if (!notificationList) return;
  const id = String(++notificationDynamicSeq);
  const li = document.createElement("li");
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "notification-item unread";
  btn.dataset.notificationId = id;
  const pt = document.createElement("p");
  pt.className = "notification-item-title";
  pt.textContent = title;
  const pm = document.createElement("p");
  pm.className = "notification-item-meta";
  pm.textContent = meta;
  btn.append(pt, pm);
  li.appendChild(btn);
  notificationList.insertBefore(li, notificationList.firstChild);
  updateNotificationBadgeCount();
}

function formatNotificationTimestampDe() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `${pad(d.getDate())}.${pad(d.getMonth() + 1)}.${d.getFullYear()}, ${pad(d.getHours())}:${pad(
    d.getMinutes(),
  )}`;
}

function randomImportLeadRef() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ";
  const pick = (len) =>
    Array.from({ length: len }, () => chars[Math.floor(Math.random() * chars.length)]).join("");
  return `IMP-${pick(2)}-${String(100 + Math.floor(Math.random() * 900))}-${pick(2)}`;
}

function appendImportedLeadRows(count) {
  const stamp = formatNotificationTimestampDe();
  for (let i = 0; i < count; i++) {
    const ref = randomImportLeadRef();
    const tr = document.createElement("tr");
    tr.className = "lead-row";
    tr.dataset.status = "Neu";
    tr.dataset.suppressLeadNotification = "1";
    tr.innerHTML = `
      <td data-col="anfragenNummer">${ref}</td>
      <td data-col="anfrageDatum">${stamp}</td>
      <td data-col="name">Import</td>
      <td data-col="bedarf">Unbekannt</td>
      <td data-col="bedarfsort">-</td>
      <td data-col="standort">Kein Gebiet</td>
      <td data-col="quelle">Importiert</td>
      <td data-col="prioritaet"><span class="chip low">Niedrig</span></td>
      <td data-col="status"><span class="status new">Neu</span></td>
      <td data-col="zustandigkeit">Nicht zugewiesen</td>
      <td data-col="zurAnfrage">
        <button class="lead-link-btn open-lead-btn" type="button">
          <i class="fa-solid fa-angle-right" aria-hidden="true"></i>
          <i class="fa-solid fa-user" aria-hidden="true"></i>
        </button>
      </td>
    `;
    leadBody.appendChild(tr);
  }
}

function initTenantLeadNotificationObserver() {
  new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      mutation.addedNodes.forEach((node) => {
        if (node.nodeType !== Node.ELEMENT_NODE) return;
        if (!node.matches("tr.lead-row")) return;
        if (node.dataset.suppressLeadNotification === "1") return;
        const nr =
          node.querySelector('[data-col="anfragenNummer"]')?.textContent?.trim() || "\u2013";
        pushAppNotification(
          "Neue Anfrage eingegangen",
          `Anfrage ${nr} ist im System verfügbar.`,
        );
      });
    });
  }).observe(leadBody, { childList: true });
}

document.addEventListener("anfragen:tenantNewLead", (event) => {
  const detail = event.detail || {};
  pushAppNotification(
    detail.title || "Neue Anfrage eingegangen",
    detail.meta || "Der Mandant hat eine neue Anfrage erhalten.",
  );
});

