function randomManualImportLeadRef() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ";
  const pick = (len) =>
    Array.from({ length: len }, () => chars[Math.floor(Math.random() * chars.length)]).join("");
  return `IMP-MAN-${pick(2)}-${String(100 + Math.floor(Math.random() * 900))}-${pick(2)}`;
}

function selectOptionText(selectEl, emptyFallback) {
  if (!selectEl) return emptyFallback;
  const opt = selectEl.options[selectEl.selectedIndex];
  if (!opt || !String(opt.value).trim()) return emptyFallback;
  return (opt.textContent || "").trim() || emptyFallback;
}

/**
 * Appends a lead row from the manual import form. Returns the generated reference.
 * suppressLeadNotification avoids duplicating the tenant notification via MutationObserver.
 */
function appendManualImportedLeadRow() {
  const stamp = formatNotificationTimestampDe();
  const ref = randomManualImportLeadRef();
  const vorEl = document.getElementById("importVorname");
  const nachEl = document.getElementById("importNachname");
  const vor = (vorEl && vorEl.value ? vorEl.value : "").trim();
  const nach = (nachEl && nachEl.value ? nachEl.value : "").trim();
  const name = `${vor} ${nach}`.trim() || "Import";
  const bedarf = selectOptionText(document.getElementById("importBedarf"), "Unbekannt");
  const plz = ((document.getElementById("importPlz") || {}).value || "").trim();
  const ort = ((document.getElementById("importOrt") || {}).value || "").trim();
  const bedarfsort = [plz, ort].filter(Boolean).join(" ") || "-";
  const quelle =
    ((document.getElementById("importQuelle") || {}).value || "").trim() || "Manueller Import";
  const tr = document.createElement("tr");
  tr.className = "lead-row";
  tr.dataset.status = "Neu";
  tr.dataset.suppressLeadNotification = "1";
  tr.innerHTML = `
      <td data-col="anfragenNummer"></td>
      <td data-col="anfrageDatum"></td>
      <td data-col="name"></td>
      <td data-col="bedarf"></td>
      <td data-col="bedarfsort"></td>
      <td data-col="standort"></td>
      <td data-col="quelle"></td>
      <td data-col="prioritaet"><span class="chip low">Niedrig</span></td>
      <td data-col="status"><span class="status new">Neu</span></td>
      <td data-col="zustandigkeit">Nicht zugewiesen</td>
      <td data-col="zurAnfrage">
        <button class="lead-link-btn open-lead-btn" type="button">
          <i class="fa-solid fa-angle-right" aria-hidden="true"></i>
          <i class="fa-solid fa-user" aria-hidden="true"></i>
        </button>
      </td>
    `;
  tr.querySelector('[data-col="anfragenNummer"]').textContent = ref;
  tr.querySelector('[data-col="anfrageDatum"]').textContent = stamp;
  tr.querySelector('[data-col="name"]').textContent = name;
  tr.querySelector('[data-col="bedarf"]').textContent = bedarf;
  tr.querySelector('[data-col="bedarfsort"]').textContent = bedarfsort;
  tr.querySelector('[data-col="standort"]').textContent = "Kein Gebiet";
  tr.querySelector('[data-col="quelle"]').textContent = quelle;
  leadBody.appendChild(tr);
  return ref;
}

