/** Uses data-lead-ref from dynamic notifications or matches seeded copy against table refs. */
function resolveLeadRefFromNotificationButton(btn) {
  const fromData = (btn.dataset.leadRef || "").trim();
  if (fromData) return fromData;
  const blob = (btn.textContent || "").replace(/\s+/g, " ");
  for (const row of getLeadRows()) {
    const cell = row.querySelector('[data-col="anfragenNummer"]');
    const nr = cell ? cell.textContent.trim() : "";
    if (nr && blob.includes(nr)) return nr;
  }
  return "";
}

