  if (!ref) {
    paragraphEl.textContent = meta;
    return;
  }

  if (link && meta.includes(link)) {
    const ix = meta.indexOf(link);
    paragraphEl.appendChild(document.createTextNode(meta.slice(0, ix)));
    paragraphEl.appendChild(spanForNavigation(link));
    paragraphEl.appendChild(document.createTextNode(meta.slice(ix + link.length)));
    return;
  }

  const ixRef = meta.indexOf(ref);
  if (ixRef !== -1) {
    paragraphEl.appendChild(document.createTextNode(meta.slice(0, ixRef)));
    paragraphEl.appendChild(spanForNavigation(ref));
    paragraphEl.appendChild(document.createTextNode(meta.slice(ixRef + ref.length)));
    return;
  }

  paragraphEl.append(meta);
  const tail = link || ref;
  if (tail) {
    const needsSep = meta.length > 0 && !/\s$/.test(meta);
    if (needsSep) paragraphEl.appendChild(document.createTextNode(" "));
    paragraphEl.appendChild(spanForNavigation(tail));
  }
}

