function showLeadDetailConfirmationToast(changeLines, notificationFollowUpDismissed, bareNeuIbOnly) {
  const lines = Array.isArray(changeLines) ? changeLines : [];
  const showToast =
    lines.length > 0 ||
    notificationFollowUpDismissed === true ||
    bareNeuIbOnly === true;
  if (!leadDetailToastStack || !showToast) return;
  clearLeadDetailConfirmationToast();

  const toast = document.createElement("div");
  toast.className = "detail-toast";
  toast.setAttribute("role", "status");

  const closeBtn = document.createElement("button");
  closeBtn.type = "button";
  closeBtn.className = "detail-toast-close";
  closeBtn.setAttribute("aria-label", "Hinweis schließen");
  closeBtn.innerHTML = '<i class="fa-solid fa-xmark" aria-hidden="true"></i>';

  const toastBody = document.createElement("div");
  toastBody.className = "detail-toast-body";

  const iconWrap = document.createElement("span");
  iconWrap.className = "detail-toast-icon";
  iconWrap.innerHTML = '<i class="fa-solid fa-check" aria-hidden="true"></i>';

  const copy = document.createElement("div");
  copy.className = "detail-toast-copy";

  const headline = document.createElement("p");
  headline.className = "detail-toast-headline";
  headline.textContent = "Änderungen wurden erfolgreich gespeichert.";

  copy.append(headline);

  if (lines.length > 0) {
    const ul = document.createElement("ul");
    ul.className = "detail-toast-list";
    lines.forEach((line) => {
      const li = document.createElement("li");
      li.textContent = line;
      ul.appendChild(li);
    });
    copy.appendChild(ul);
  }

  if (notificationFollowUpDismissed) {
    const follow = document.createElement("p");
    follow.className = "detail-toast-followup";
    follow.textContent =
      "Die Anfrage ist jetzt „In Bearbeitung“ – Die Aufgabe „Anfragenbearbeitung Starten“ ist schon geschafft.";
    copy.appendChild(follow);
  }

  toastBody.append(iconWrap, copy);

  const bar = document.createElement("div");
  bar.className = "detail-toast-bar";
  const fill = document.createElement("div");
  fill.className = "detail-toast-bar-fill";
  bar.appendChild(fill);

  toast.append(closeBtn, toastBody, bar);
  leadDetailToastStack.appendChild(toast);

  const removeToast = () => {
    if (leadDetailToastHideTimer) {
      clearTimeout(leadDetailToastHideTimer);
      leadDetailToastHideTimer = null;
    }
    toast.remove();
  };

  closeBtn.addEventListener("click", removeToast);

  leadDetailToastHideTimer = setTimeout(removeToast, 5600);
}

function handleLeadDetailControlChange(which) {
  const row = leadDetailActiveRow;
  if (!row || !leadDetailPage.classList.contains("open")) return;

  const lines = [];
  let notificationCleared = false;
  let bareNeuIbOnly = false;

  if (which === "status" && detailStatusSelect) {
    const previous = row.dataset.status || "";
    const newStatus = detailStatusSelect.value;
    if (previous === newStatus) return;
    syncLeadRowStatusFromDetailSelect(row, newStatus);
    const neuToIb = previous === "Neu" && newStatus === "In Bearbeitung";
    if (!neuToIb) {
      lines.push(`Status: „${previous}“ → „${newStatus}“`);
    }
    if (neuToIb) {
      const nr = row.querySelector('[data-col="anfragenNummer"]')?.textContent?.trim() || "";
      notificationCleared = markFreshLeadNotificationsHandledForBadge(nr);
      if (!notificationCleared) bareNeuIbOnly = true;
    }
  } else if (which === "standort" && detailStandortSelect) {
    const prev = getCellValue(row, "standort");
    const next = detailStandortSelect.value;
    if (prev === next) return;
    syncLeadRowPlainColumn(row, "standort", next);
    lines.push(`Gebiet: „${prev}“ → „${next}“`);
  } else if (which === "owner" && detailOwnerSelect) {
    const prev = getCellValue(row, "zustandigkeit");
    const next = detailOwnerSelect.value;
    if (prev === next) return;
    syncLeadRowPlainColumn(row, "zustandigkeit", next);
    lines.push(`Zuständigkeit: „${prev}“ → „${next}“`);
  }

  if (lines.length || notificationCleared || bareNeuIbOnly) {
    showLeadDetailConfirmationToast(lines, notificationCleared, bareNeuIbOnly);
  }
}

