function getCurrentUserName() {
  return (sidebarUserName?.textContent || "").trim();
}

function notificationBelongsToCurrentUser(btn) {
  const recipient = (btn?.dataset?.recipientUser || "").trim();
  const current = getCurrentUserName();
  return !recipient || (current && recipient === current);
}

function buildUserNotificationCopy(kind, payload) {
  const p = payload || {};
  const leadRef = typeof p.leadRef === "string" ? p.leadRef.trim() : "";
  const zur = notificationZurAnfragePhrase(p.leadName, leadRef);
  switch (kind) {
    case "task_assigned": {
      const by = typeof p.assignedBy === "string" ? p.assignedBy.trim() : "";
      const current = getCurrentUserName();
      const bySuffix = by && by !== current ? `von ${by}` : "";
      let meta = bySuffix;
      if (zur) meta = meta ? `${meta} · ${zur}` : zur;
      else if (leadRef) meta = meta ? `${meta} · ${leadRef}` : leadRef;
      return { title: "Anfrage übernehmen", meta: meta || "Neue Aufgabe für Sie" };
    }
    case "client_won": {
      const winner =
        typeof p.winnerName === "string" && p.winnerName.trim()
          ? p.winnerName.trim()
          : "Ein Kollege";
      return {
        title: "Klient gewonnen",
        meta: `${winner} hat einen Klienten gewonnen.`,
      };
    }
    case "new_lead": {
      let meta = "Jetzt kontaktieren";
      if (zur) meta = `${meta} · ${zur}`;
      else if (leadRef) meta = `${meta} · ${leadRef}`;
      return { title: "Neue Anfrage verfügbar", meta };
    }
    case "reminder": {
      const n = Math.max(0, Number(p.taskCount) || 0);
      const meta =
        n === 0
          ? "Keine offenen Anfragen für heute"
          : n === 1
            ? "1 Anfrage für heute offen"
            : `${n} Anfragen für heute offen`;
      return { title: "Heute erledigen", meta };
    }
    default:
      return {
        title: typeof p.title === "string" ? p.title : "Hinweis",
        meta: typeof p.meta === "string" ? p.meta : "",
      };
  }
}

function pushUserNotification(options) {
  const opts = options || {};
  const recipient = (opts.recipientUser || getCurrentUserName()).trim();
  const current = getCurrentUserName();
  if (!recipient || recipient !== current) return null;
  const kind = typeof opts.kind === "string" ? opts.kind.trim() : "";
  const copy = buildUserNotificationCopy(kind, opts);
  const title =
    typeof opts.title === "string" && opts.title.trim() ? opts.title.trim() : copy.title;
  const meta =
    typeof opts.meta === "string" && opts.meta.trim() ? opts.meta.trim() : copy.meta;
  return pushAppNotification(title, meta, {
    leadRef: opts.leadRef,
    leadName: opts.leadName,
    recipientUser: recipient,
    notificationKind: kind,
    assignee: opts.assignee,
    assignmentNotification: kind === "task_assigned",
    freshLeadNotification: kind === "new_lead",
  });
}

function countOpenTasksForUser(userName) {
  const user = (userName || "").trim();
  if (!user) return 0;
  return getLeadRows().filter((row) => {
    if (getCellValue(row, "zustandigkeit") !== user) return false;
    const status = (row.dataset.status || getCellValue(row, "status") || "").trim();
    return status === "Neu" || status === "In Bearbeitung";
  }).length;
}

