function getLeadRefFromRow(row) {
  return getCellValue(row, "anfragenNummer");
}

function getUserInitials(name) {
  const parts = String(name || "")
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  if (!parts.length) return "?";
  return parts
    .map((p) => p[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

function formatTodayDuePill() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `fällig heute: ${pad(d.getDate())}.${pad(d.getMonth() + 1)}.${d.getFullYear()}`;
}

function ensureFirstContactTaskForLead(row) {
  if (!row) return null;
  const leadRef = getLeadRefFromRow(row);
  if (!leadRef || leadRef === "-" || leadRef === "\u2013") return null;
  const status = (row.dataset.status || getCellValue(row, "status") || "").trim();
  if (status !== "Neu") return tenantLeadTasks.get(leadRef) || null;

  let task = tenantLeadTasks.get(leadRef);
  if (!task) {
    task = {
      leadRef,
      type: FIRST_CONTACT_TASK_TYPE,
      title: FIRST_CONTACT_TASK_TITLE,
      subtitle: FIRST_CONTACT_TASK_SUBTITLE,
      assignee: null,
      completed: false,
    };
    tenantLeadTasks.set(leadRef, task);
  }

  const owner = getCellValue(row, "zustandigkeit");
  if (owner && owner !== "Nicht zugewiesen") {
    task.assignee = owner;
  }
  return task;
}

function syncFirstContactAssigneeFromLead(row, assignee) {
  const leadRef = getLeadRefFromRow(row);
  const task = tenantLeadTasks.get(leadRef);
  if (!task || task.completed || task.type !== FIRST_CONTACT_TASK_TYPE) return;
  if (!assignee || assignee === "Nicht zugewiesen") {
    task.assignee = null;
  } else {
    task.assignee = assignee;
  }
  if (leadDetailActiveRow === row) renderLeadDetailTasks(row);
}

function completeFirstContactTaskForLead(leadRef) {
  const task = tenantLeadTasks.get(leadRef);
  if (!task || task.completed || task.type !== FIRST_CONTACT_TASK_TYPE) return false;
  task.completed = true;
  task.completedAt = Date.now();
  return true;
}

function registerIncomingLeadRow(row) {
  ensureFirstContactTaskForLead(row);
}

function initFirstContactTasksForExistingLeads() {
  getLeadRows().forEach((row) => {
    const status = (row.dataset.status || getCellValue(row, "status") || "").trim();
    if (status === "Neu") registerIncomingLeadRow(row);
  });
}

function renderLeadDetailTasks(row) {
  if (!leadDetailTasksList || !row) return;
  const leadRef = getLeadRefFromRow(row);
  ensureFirstContactTaskForLead(row);
  const tasks = [...tenantLeadTasks.values()].filter(
    (t) => t.leadRef === leadRef && t.type === FIRST_CONTACT_TASK_TYPE,
  );
  const openTasks = tasks.filter((t) => !t.completed);
  const displayTasks = openTasks.length ? openTasks : tasks;

  leadDetailTasksList.innerHTML = "";
  const total = displayTasks.length;
  if (leadDetailTasksCount) {
    leadDetailTasksCount.textContent = String(openTasks.length);
  }
  if (leadDetailTasksFooter) {
    leadDetailTasksFooter.textContent =
      total === 0
        ? "0-0 von 0 · Seite 1 / 1"
        : `1-${total} von ${total} · Seite 1 / 1`;
  }
  if (!total) return;

  displayTasks.forEach((task) => {
    const rowEl = document.createElement("motion");
    rowEl.className = `list-row lead-task-row${task.completed ? " completed" : ""}`;
    rowEl.dataset.leadRef = task.leadRef;
    rowEl.dataset.taskType = task.type;

    const left = document.createElement("div");
    left.className = "list-row-left";
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.checked = task.completed;
    checkbox.disabled = task.completed;
    checkbox.dataset.firstContactTask = "1";
    checkbox.setAttribute(
      "aria-label",
      task.completed ? "Erstkontakt erledigt" : "Erstkontakt als erledigt markieren",
    );
    const textWrap = document.createElement("div");
    const titleEl = document.createElement("div");
    titleEl.className = "lead-task-title";
    titleEl.style.fontWeight = "700";
    titleEl.textContent = task.title;
    const subEl = document.createElement("div");
    subEl.className = "lead-task-subtitle";
    subEl.textContent = task.subtitle;
    textWrap.append(titleEl, subEl);
    left.append(checkbox, textWrap);

    const right = document.createElement("div");
    right.className = "list-row-right";
    const duePill = document.createElement("span");
    duePill.className = `pill ${task.completed ? "pill-blue" : "pill-red"}`;
    duePill.textContent = task.completed ? "Erledigt" : formatTodayDuePill();
    const tenantPill = document.createElement("span");
    tenantPill.className = "pill lead-task-tenant-pill";
    tenantPill.textContent = task.assignee ? task.assignee : "Mandant";
    const avatar = document.createElement("span");
    avatar.className = `avatar-mini${task.assignee ? "" : " avatar-tenant"}`;
    avatar.textContent = task.assignee ? getUserInitials(task.assignee) : "Alle";
    avatar.title = task.assignee || "Mandantenweit – noch nicht zugewiesen";
    right.append(duePill, tenantPill, avatar);

    rowEl.append(left, right);
    leadDetailTasksList.appendChild(rowEl);
  });
}

