function buildUniqueDemoNamePairs(count) {
  const pairs = [];
  const used = new Set();
  for (let fi = 0; fi < DEMO_FIRST_NAMES.length && pairs.length < count; fi++) {
    for (let li = 0; li < DEMO_LAST_NAMES.length && pairs.length < count; li++) {
      const first = DEMO_FIRST_NAMES[fi];
      const last = DEMO_LAST_NAMES[li];
      const key = `${last}\u0000${first}`;
      if (used.has(key)) continue;
      used.add(key);
      pairs.push({ first, last, display: `${last}, ${first}` });
    }
  }
  return pairs;
}

function bedarfProductForDemoIndex(index, total) {
  const slot = Math.floor((index * LEAD_BEDARF_PRODUCTS.length) / total);
  return LEAD_BEDARF_PRODUCTS[Math.min(slot, LEAD_BEDARF_PRODUCTS.length - 1)];
}

function formatLeadDateDaysAgo(daysAgo) {
  const d = new Date();
  d.setDate(d.getDate() - daysAgo);
  d.setHours(8 + (daysAgo % 10), (daysAgo * 7) % 60, 0, 0);
  const pad = (n) => String(n).padStart(2, "0");
  return `${pad(d.getDate())}.${pad(d.getMonth() + 1)}.${d.getFullYear()}, ${pad(d.getHours())}:${pad(
    d.getMinutes(),
  )}`;
}

function generateDemoLeadRef(seq) {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ";
  const a = chars[(seq * 3) % chars.length];
  const b = chars[(seq * 11 + 5) % chars.length];
  return `VIA-DMO-${String(100 + seq).padStart(3, "0")}-${a}${b}`;
}

