function seedBulkDemoLeads(count) {
  if (!leadBody || count < 1) return;
  const names = buildUniqueDemoNamePairs(count);
  const statuses = ["Neu", "In Bearbeitung", "Geschlossen"];
  const priorities = ["Niedrig", "Mittel", "Hoch"];
  const standorte = [...OVERVIEW_STANDORT_OPTIONS, "Kein Gebiet"];
  const owners = [...OVERVIEW_OWNER_OPTIONS, "Nicht zugewiesen"];

  for (let i = 0; i < count; i++) {
    const person = names[i];
    const loc = DEMO_BEDARFSORTE[i % DEMO_BEDARFSORTE.length];
    const status = statuses[i % statuses.length];
    appendDemoLeadRow({
      ref: generateDemoLeadRef(i + 1),
      datum: formatLeadDateDaysAgo(i % 120),
      name: person.display,
      bedarf: bedarfProductForDemoIndex(i, count),
      bedarfsort: `${loc.plz} ${loc.ort}`,
      standort: standorte[i % standorte.length],
      quelle: DEMO_QUELLEN[i % DEMO_QUELLEN.length],
      prioritaet: priorities[i % priorities.length],
      status,
      zustandigkeit: owners[i % owners.length],
    });
  }
  updateLeadTableRangeLabel();
}

