function updateLeadTablePaginationUi(filteredCount, rangeStart, rangeEnd) {
  if (leadTableRangeLabel) {
    leadTableRangeLabel.textContent =
      filteredCount === 0 ? "0-0 von 0" : `${rangeStart}-${rangeEnd} von ${filteredCount}`;
  }
  const totalPages = Math.max(1, Math.ceil(filteredCount / leadTablePageSize));
  if (leadPagePrev) {
    leadPagePrev.disabled = filteredCount === 0 || leadTablePage <= 1;
  }
  if (leadPageNext) {
    leadPageNext.disabled = filteredCount === 0 || leadTablePage >= totalPages;
  }
}

function applyFilter(resetPage) {
  if (resetPage) leadTablePage = 1;

  const filtered = getFilteredLeadRows();
  const total = filtered.length;
  const totalPages = Math.max(1, Math.ceil(total / leadTablePageSize));
  if (leadTablePage > totalPages) leadTablePage = totalPages;
  if (leadTablePage < 1) leadTablePage = 1;

  const startIndex = (leadTablePage - 1) * leadTablePageSize;
  const endIndex = Math.min(startIndex + leadTablePageSize, total);

  getLeadRows().forEach((row) => {
    row.style.display = "none";
  });
  filtered.forEach((row, index) => {
    if (index >= startIndex && index < endIndex) {
      row.style.display = "";
    }
  });

  updateLeadTablePaginationUi(
    total,
    total === 0 ? 0 : startIndex + 1,
    total === 0 ? 0 : endIndex,
  );
}

