function setTaskCountBadge(badgeEl, count) {
  if (!badgeEl) return;
  if (count <= 0) {
    badgeEl.hidden = true;
    badgeEl.setAttribute("aria-hidden", "true");
    badgeEl.textContent = "";
    return;
  }
  badgeEl.hidden = false;
  badgeEl.removeAttribute("aria-hidden");
  badgeEl.textContent = count > 99 ? "99+" : String(count);
}

