function cancelPendingQuickAccessToastBatch() {
  if (quickAccessToastFlushTimer) {
    clearTimeout(quickAccessToastFlushTimer);
    quickAccessToastFlushTimer = null;
  }
  pendingQuickAccessToastEntries = [];
}

function getQuickAccessToastSummary(entry) {
  if (!entry) return "";
  if (entry.summary) return entry.summary;
  if (entry.kind === "success") return entry.message || "";
  if (entry.kind === "status") {
    const label = (entry.statusLabel || "").trim();
    return label ? `Status: „${label}“` : "Status geändert";
  }
  if (entry.kind === "assignee") {
    const next = (entry.nextAssignee || "").trim();
    if (next && next !== "Nicht zugewiesen") {
      return `Zuständigkeit: ${next}`;
    }
    return "Zuständigkeit entfernt";
  }
  return "";
}

function queueQuickAccessToast(entry) {
  if (!entry) return;
  pendingQuickAccessToastEntries.push(entry);
  if (quickAccessToastFlushTimer) {
    clearTimeout(quickAccessToastFlushTimer);
  }
  quickAccessToastFlushTimer = setTimeout(flushQuickAccessToastBatch, QUICK_ACCESS_TOAST_BATCH_MS);
}

function flushQuickAccessToastBatch() {
  quickAccessToastFlushTimer = null;
  const batch = pendingQuickAccessToastEntries.splice(0);
  if (!batch.length) return;
  if (batch.length <= 2) {
    batch.forEach((entry) => renderQuickAccessToastEntry(entry));
    return;
  }
  showGroupedQuickAccessToast(batch);
}

function renderQuickAccessToastEntry(entry) {
  if (!entry) return;
  if (entry.kind === "success") {
    showSuccessStateToast(entry.message);
    return;
  }
  if (entry.kind === "status") {
    showLeadDetailConfirmationToast(entry.notificationCleared, entry.statusLabel);
    return;
  }
  if (entry.kind === "assignee") {
    showAssigneeChangeToast(entry.row, entry.previousAssignee, entry.nextAssignee, {
      skipSideEffects: true,
    });
  }
}

function showGroupedQuickAccessToast(entries) {
  if (!leadDetailToastStack || !entries.length) return;
  const { toast, closeBtn, copy } = appendBaseToast();
  toast.style.setProperty("--toast-progress-duration", "5s");
  const headline = document.createElement("p");
  headline.className = "detail-toast-headline";
  headline.textContent = `${entries.length} Änderungen gespeichert`;
  const list = document.createElement("ul");
  list.className = "detail-toast-change-list";
  entries.forEach((entry) => {
    const li = document.createElement("li");
