function expandToastStack() {
  if (!leadDetailToastStack) return;
  leadDetailToastStack.classList.remove("is-collapsed");
  leadDetailToastStack.classList.add("is-expanded");
  leadDetailToastStack.querySelectorAll(".toast-stack-hint").forEach((el) => el.remove());
  leadDetailToastStack.querySelectorAll(".toast-stack-count").forEach((el) => el.remove());
}

function collapseToastStackIfNeeded() {
  if (!leadDetailToastStack) return;
  const count = getVisibleToastCount();
  if (count <= 1) {
    leadDetailToastStack.classList.remove("is-collapsed", "is-expanded");
    leadDetailToastStack.querySelectorAll(".toast-stack-hint, .toast-stack-count").forEach((el) => {
      el.remove();
    });
    return;
  }
  if (leadDetailToastStack.classList.contains("is-expanded")) {
    return;
  }
  leadDetailToastStack.classList.add("is-collapsed");
  leadDetailToastStack.classList.remove("is-expanded");
  const front = leadDetailToastStack.querySelector(".detail-toast:first-child");
  if (!front) return;
  if (!front.querySelector(".toast-stack-count")) {
    const badge = document.createElement("span");
    badge.className = "toast-stack-count";
    badge.textContent = String(count);
    badge.setAttribute("aria-hidden", "true");
    front.appendChild(badge);
  } else {
    front.querySelector(".toast-stack-count").textContent = String(count);
  }
  if (!front.querySelector(".toast-stack-hint")) {
    const hint = document.createElement("p");
    hint.className = "toast-stack-hint";
    hint.textContent = "Klicken, um alle Hinweise anzuzeigen";
    front.appendChild(hint);
  }
}

function updateToastStackLayout() {
  collapseToastStackIfNeeded();
}

function mountToastInStack(toast) {
  if (!leadDetailToastStack || !toast) return;
