    if (onEmailAnimationEnd && fill) {
      fill.removeEventListener("animationend", onEmailAnimationEnd);
      onEmailAnimationEnd = null;
    }
  };

  const removeToast = () => {
    clearAssigneeToastTimers();
    detachEmailAnimationEnd();
    delete toast._assigneeUndoController;
    toast.remove();
    if (undoStack?.classList?.contains("lead-detail-toast-stack")) {
      if (!undoStack.querySelector(".detail-toast")) {
        undoStack.classList.remove("is-collapsed", "is-expanded");
      } else {
        updateToastStackLayoutFor(undoStack);
      }
    }
  };

  const completeEmailSend = () => {
    if (emailSendCompleted) return;
    emailSendCompleted = true;
    clearAssigneeToastTimers();
    detachEmailAnimationEnd();
    delete row.dataset.pendingAssigneeInitial;
    removeToast();
    showSuccessStateToast("E-Mail-Benachrichtigung wurde versendet.");
  };

  const startAssigneeToastTimers = (nextAssignee) => {
    clearAssigneeToastTimers();
    detachEmailAnimationEnd();
    emailSendCompleted = false;

    const sendsEmail = renderAssigneeUndoToastMessage(msg, nextAssignee);
    toast.style.setProperty("--toast-progress-duration", "8s");
    if (fill) {
