        showSimpleConfirmationToast(confirmationMsg);
      }, 8000);
    }
  };

  const restart = (nextAssignee) => {
    startAssigneeToastTimers(nextAssignee);
    if (undoStack && undoStack.firstChild !== toast) {
      undoStack.insertBefore(toast, undoStack.firstChild);
    }
    updateToastStackLayoutFor(undoStack);
  };

  closeBtn.addEventListener("click", (e) => {
    e.stopPropagation();
