function ensureLeadOpenButtonTaskBadge(button) {
  if (!button) return null;
  let badge = button.querySelector(".lead-task-due-badge");
  if (!badge) {
    badge = document.createElement("span");
    badge.className = "lead-task-due-badge";
    badge.hidden = true;
    button.appendChild(badge);
  }
  return badge;
}

function updateTaskDueBadges() {
  const user = getCurrentUserName();
  const totalDue = countOpenTasksForUser(user);
  const menuBadge = document.getElementById("menuAufgabenTaskBadge");
  setTaskCountBadge(menuBadge, totalDue);
  if (menuAufgabenBtn) {
    menuAufgabenBtn.classList.toggle("has-task-due-badge", totalDue > 0);
  }

  getLeadRows().forEach((row) => {
    const button = row.querySelector(".open-lead-btn");
    const badge = ensureLeadOpenButtonTaskBadge(button);
    const leadRef = getLeadRefFromRow(row);
    setTaskCountBadge(badge, countDueTodayTasksForUserOnLead(leadRef, user));
  });
}

