/** Demo: exactly `count` open Erstkontakt tasks due today on the first LO page for the current user. */
function configureDueTodayTasksOnFirstListPage(count = 4) {
  const user = getCurrentUserName();
  if (!user) return;

  tenantLeadTasks.forEach((task) => {
    if (task.type !== FIRST_CONTACT_TASK_TYPE) return;
    task.completed = true;
    delete task.completedAt;
  });

  const targets = getFilteredLeadRows().slice(0, count);
  targets.forEach((row) => {
    syncLeadRowStatusFromDetailSelect(row, "Neu");
    syncLeadRowPlainColumn(row, "zustandigkeit", user);
    renderOverviewInlineSelectCell(row, "zustandigkeit", user);

    const leadRef = getLeadRefFromRow(row);
    if (!leadRef) return;

    ensureFirstContactTaskForLead(row);
    const task = tenantLeadTasks.get(leadRef);
    if (!task) return;

    task.type = FIRST_CONTACT_TASK_TYPE;
    task.title = FIRST_CONTACT_TASK_TITLE;
    task.subtitle = FIRST_CONTACT_TASK_SUBTITLE;
    task.completed = false;
    delete task.completedAt;
    task.dueDate = formatDateKeyLocal(new Date());
    task.assignee = user;
  });

  updateTaskDueBadges();
}

