input.new_string:
let lastSyncedReminderTaskCount = null;

function getReminderNotificationItem() {
  if (!notificationList) return null;
  return (
    [...notificationList.querySelectorAll(
      '.notification-item[data-notification-kind="reminder"]',
    )].find((el) => notificationBelongsToCurrentUser(el)) || null
  );
}

function renderReminderNotificationContent(btn, taskCount) {
  if (!btn) return;
  const copy = buildUserNotificationCopy("reminder", { taskCount });
  const pinnedCopy = btn.querySelector(".notification-item-pinned-copy");
  if (!pinnedCopy) return;

  let titleEl = pinnedCopy.querySelector(".notification-item-title");
  if (!titleEl) {
    titleEl = document.createElement("p");
    titleEl.className = "notification-item-title";
    pinnedCopy.insertBefore(titleEl, pinnedCopy.firstChild);
  }
  titleEl.textContent = copy.title;

  let metaEl = pinnedCopy.querySelector(".notification-item-meta");
  if (copy.meta.trim()) {
    if (!metaEl) {
      metaEl = document.createElement("p");
      metaEl.className = "notification-item-meta";
      pinnedCopy.appendChild(metaEl);
    }
    appendNotificationAufgabenLink(metaEl, copy.meta.trim());
  } else if (metaEl) {
    metaEl.remove();
  }
}

function syncDailyReminderNotification() {
  updateTaskDueBadges();
  const user = getCurrentUserName();
  if (!user) return;
  const count = countOpenTasksForUser(user);
  const existing = getReminderNotificationItem();
  const previousCount = lastSyncedReminderTaskCount;
  const countIncreased = previousCount !== null && count > previousCount;

  if (existing) {
    renderReminderNotificationContent(existing, count);
    if (countIncreased) {
      delete existing.dataset.badgeAcknowledged;
      if (!existing.classList.contains("is-read")) {
        existing.classList.remove("is-seen");
        existing.classList.add("unread");
      }
    }
  } else {
    removeUserNotificationsByKind("reminder", user);
    pushUserNotification({ kind: "reminder", recipientUser: user, taskCount: count });
  }

  lastSyncedReminderTaskCount = count;
  updateNotificationBadgeCount();
}

