function salesContactEmailFromName(fullName) {
  const parts = String(fullName || "")
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  if (parts.length < 2) return "";
  const normalize = (s) =>
    s
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z]/g, "");
  const first = normalize(parts[0]);
  const last = normalize(parts[parts.length - 1]);
  if (!first || !last) return "";
  return `${first}.${last}@carelink-solutions.de`;
}

function phoneDisplayToTelHref(displayPhone) {
  let digits = String(displayPhone || "").replace(/\D/g, "");
  if (!digits) return "";
  if (digits.startsWith("49")) {
    return `tel:+${digits}`;
  }
  if (digits.startsWith("0")) {
    digits = digits.slice(1);
  }
  return `tel:+49${digits}`;
}

function helpContactRoleLabel(contactName) {
  const first = String(contactName || "")
    .trim()
    .split(/\s+/)[0];
  if (!first) return "Ihre Ansprechperson";
  const femaleNames = new Set([
    "lea",
    "sara",
    "anna",
    "maria",
    "julia",
    "lisa",
    "sophie",
    "lena",
  ]);
  const key = first.toLowerCase();
  const salutation = femaleNames.has(key) ? "Ihre Ansprechpartnerin" : "Ihr Ansprechpartner";
  const role =
    (headerContactBlock?.dataset.contactRole || "Vertrieb & Kundenerfolg").trim() ||
    "Vertrieb & Kundenerfolg";
  return `${salutation} · ${role}`;
}

function getHeaderSalesContact() {
  const block =
    headerContactBlock || document.querySelector(".header-contact");
  const nameEl = block?.querySelector(".header-contact-name");
  const phoneEl = block?.querySelector(".header-contact-phone");
  const name = (nameEl?.textContent || "").trim();
  const phone = (phoneEl?.textContent || "").trim();
  const email =
    (block?.dataset.contactEmail || "").trim() || salesContactEmailFromName(name);
  const avatarBtn = headerContactAvatarBtn;
  const initials =
    (avatarBtn?.textContent || "").trim() || getUserInitials(name);
  return { name, phone, email, initials };
}

function syncHelpCenterSalesContact() {
  const contact = getHeaderSalesContact();
  if (helpContactAvatar) {
    helpContactAvatar.textContent = contact.initials || "—";
  }
  if (helpContactName) {
    helpContactName.textContent = contact.name || "—";
  }
  if (helpContactRole) {
    helpContactRole.textContent = contact.name
      ? helpContactRoleLabel(contact.name)
      : "—";
  }
  if (helpContactEmailLink) {
    if (contact.email) {
      helpContactEmailLink.href = `mailto:${contact.email}`;
      helpContactEmailLink.textContent = contact.email;
    } else {
      helpContactEmailLink.removeAttribute("href");
      helpContactEmailLink.textContent = "—";
    }
  }
  if (helpContactPhoneLink) {
    if (contact.phone) {
      const tel = phoneDisplayToTelHref(contact.phone);
      helpContactPhoneLink.href = tel || "#";
      helpContactPhoneLink.textContent = contact.phone;
    } else {
      helpContactPhoneLink.removeAttribute("href");
      helpContactPhoneLink.textContent = "—";
    }
  }
  if (helpContactSuccessName) {
    helpContactSuccessName.textContent = contact.name || "Ihre Ansprechperson";
  }
}

