input.new_string:
  const VIEWPORT_STORAGE_KEY = "anfragen-manager-viewport";
  const viewportToggle = document.getElementById("viewportToggle");
  const viewportToggleLabel = document.getElementById("viewportToggleLabel");
  const viewportMobileMenuBtn = document.getElementById("viewportMobileMenuBtn");
  const viewportSidebarBackdrop = document.getElementById("viewportSidebarBackdrop");
  const viewportPreviewBanner = document.getElementById("viewportPreviewBanner");
  const sidebarNav = document.getElementById("sidebarNav");

  function isViewportMobile() {
    return document.body.classList.contains("viewport-mobile");
  }

  function closeMobileSidebar() {
    sidebarNav?.classList.remove("is-open");
    viewportSidebarBackdrop?.setAttribute("hidden", "");
    if (viewportMobileMenuBtn) {
      viewportMobileMenuBtn.setAttribute("aria-expanded", "false");
      viewportMobileMenuBtn.setAttribute("aria-label", "Menü öffnen");
    }
  }

  function openMobileSidebar() {
    if (!isViewportMobile()) return;
    sidebarNav?.classList.add("is-open");
    viewportSidebarBackdrop?.removeAttribute("hidden");
    if (viewportMobileMenuBtn) {
      viewportMobileMenuBtn.setAttribute("aria-expanded", "true");
      viewportMobileMenuBtn.setAttribute("aria-label", "Menü schließen");
    }
  }

  function toggleMobileSidebar() {
    if (!isViewportMobile()) return;
    if (sidebarNav?.classList.contains("is-open")) {
      closeMobileSidebar();
    } else {
      openMobileSidebar();
    }
  }

  function syncViewportToggleUi() {
    const mobile = isViewportMobile();
    if (viewportToggle) {
      viewportToggle.setAttribute("aria-pressed", String(mobile));
      viewportToggle.setAttribute(
        "aria-label",
        mobile ? "Desktop-Ansicht aktivieren" : "Mobile-Ansicht aktivieren",
      );
    }
    if (viewportToggleLabel) {
      viewportToggleLabel.textContent = mobile ? "Desktop" : "Mobile";
    }
    if (viewportMobileMenuBtn) {
      if (mobile) {
        viewportMobileMenuBtn.removeAttribute("hidden");
      } else {
        viewportMobileMenuBtn.setAttribute("hidden", "");
        closeMobileSidebar();
      }
    }
    if (viewportPreviewBanner) {
      viewportPreviewBanner.setAttribute("aria-hidden", mobile ? "false" : "true");
    }
  }

  function setViewportMode(mode) {
    const mobile = mode === "mobile";
    document.body.classList.toggle("viewport-mobile", mobile);
    try {
      sessionStorage.setItem(VIEWPORT_STORAGE_KEY, mobile ? "mobile" : "desktop");
    } catch (_) {
      /* ignore */
    }
    syncViewportToggleUi();
  }

  function initViewportToggle() {
    let stored = "";
    try {
      stored = sessionStorage.getItem(VIEWPORT_STORAGE_KEY) || "";
    } catch (_) {
      /* ignore */
    }
    setViewportMode(stored === "mobile" ? "mobile" : "desktop");

    viewportToggle?.addEventListener("click", () => {
      setViewportMode(isViewportMobile() ? "desktop" : "mobile");
    });
    viewportMobileMenuBtn?.addEventListener("click", toggleMobileSidebar);
    viewportSidebarBackdrop?.addEventListener("click", closeMobileSidebar);

    document.querySelectorAll(".menu-item, .logout").forEach((btn) => {
      btn.addEventListener("click", closeMobileSidebar);
    });
  }

  initViewportToggle();

  getLeadRows().forEach(enhanceLeadOverviewInlineSelects);
  getLeadRows().forEach(syncLeadRowQuelleDataset);
  applyFilter(true);
  applyColumnConfig();
  applyUploadedPreviewDefaults();
  updateSidebarAvatar();
  avvVersionLink.href = AVV_FILE_URL;
  avvVersionLink.target = "_blank";
  avvVersionLink.rel = "noopener noreferrer";
  updateAvvConsentUI();
</script>

