  const bannerHeight = Math.ceil(banner?.getBoundingClientRect().height || 0);
  const topbarHeight = Math.ceil(topbar?.getBoundingClientRect().height || 0);
  const separatorHeight = Math.ceil(separator?.getBoundingClientRect().height || 0);
