function activateStatsTab(tabKey) {
  const panelByTab = {
    overview: "statsPanelOverview",
    details: "statsPanelDetails",
    evaluations: "statsPanelEvaluations",
  };
  const activePanelId = panelByTab[tabKey] || panelByTab.overview;
  document.querySelectorAll(".stats-tab").forEach((btn) => {
    const isActive = btn.dataset.statsTab === tabKey;
    btn.classList.toggle("is-active", isActive);
    btn.setAttribute("aria-selected", String(isActive));
  });
  document.querySelectorAll(".stats-tab-panel").forEach((panel) => {
    const isActive = panel.id === activePanelId;
    panel.classList.toggle("is-active", isActive);
    if (isActive) {
      panel.removeAttribute("hidden");
    } else {
      panel.setAttribute("hidden", "");
    }
  });
}

