const PERF_PERIOD_DATA = {
  gesamt: PERF_BASE_DATA,
  "30d": PERF_BASE_DATA,
  "60d": PERF_BASE_DATA,
  day: null,
  "7d": null,
};

const perfSegmentState = new WeakMap();

function getPerformancePeriod() {
  return document.getElementById("statsPerformancePeriod")?.value || "gesamt";
}

function getPerfMetricData(metric, period) {
  const bucket = PERF_PERIOD_DATA[period];
  if (!bucket) return null;
  return bucket[metric] || null;
}

function formatPerfValue(metric, value) {
  if (value == null || Number.isNaN(value)) return "—";
  if (metric === "investment") return `${Math.round(value)} €`;
  return `${value.toFixed(1).replace(".", ",")}%`;
}

function parsePerfSummaryValue(metric, text) {
  if (!text || text === "—") return null;
  if (metric === "investment") {
    const n = parseInt(String(text).replace(/[^\d]/g, ""), 10);
    return Number.isFinite(n) ? n : null;
  }
  const n = parseFloat(String(text).replace("%", "").replace(",", ".").trim());
  return Number.isFinite(n) ? n : null;
}

function getDimensionKeys(metric, period, dimension) {
  const dim = getPerfMetricData(metric, period)?.[dimension];
  if (!dim?.flat) return [];
  return Object.keys(dim.flat);
}

function getFlatRows(metric, period, dimension) {
  const dim = getPerfMetricData(metric, period)?.[dimension];
  if (!dim?.flat) return [];
  return Object.entries(dim.flat).map(([label, value]) => ({ label, value, kind: "flat" }));
}

function getComboRows(metric, period, primary, secondary, selectedKeys, detailLevel) {
  const dim = getPerfMetricData(metric, period)?.[primary];
  if (!dim?.flat) return [];
  const keys = Object.keys(dim.flat).filter((key) => selectedKeys[key] !== false);
  if (!secondary) {
    return keys.map((label) => ({ label, value: dim.flat[label], kind: "flat" }));
  }
  const rows = [];
  keys.forEach((parent) => {
    rows.push({ label: parent, value: dim.flat[parent], kind: "parent" });
    if (detailLevel === "detail" && dim.nested?.[parent]) {
      Object.entries(dim.nested[parent]).forEach(([child, value]) => {
        rows.push({ label: child, value, kind: "child", parent });
      });
    }
  });
  return rows;
}

function comboLabel(primary, secondary) {
  if (!secondary) return PERF_DIM_LABELS[primary] || primary;
  return `${PERF_DIM_LABELS[primary] || primary} × ${PERF_DIM_LABELS[secondary] || secondary}`;
}

function calcBarWidths(rows, metric, refValue) {
  const nums = rows.map((r) => r.value).filter((v) => typeof v === "number");
  let max = nums.length ? Math.max(...nums) : 1;
  if (refValue != null) max = Math.max(max, refValue);
  if (metric === "investment") {
    const min = nums.length ? Math.min(...nums) : 0;
    const span = Math.max(max - min, 1);
    return rows.map((row) => ({
      ...row,
      width: typeof row.value === "number" ? Math.max(8, ((max - row.value) / span) * 100) : 0,
    }));
  }
  return rows.map((row) => ({
    ...row,
    width: typeof row.value === "number" ? Math.max(4, (row.value / max) * 100) : 0,
  }));
}

function renderPerfBarChart(container, rows, metric, options = {}) {
  if (!container) return;
  const meta = PERF_METRIC_META[metric];
  const fillClass = options.fillClass || meta?.fill || "blue";
  const comboIndex = options.comboIndex;
  const fillExtra = comboIndex != null ? ` combo-${comboIndex}` : "";
  const refValue = options.refValue ?? null;
  if (!rows.length) {
    container.innerHTML = '<p class="stats-perf-empty">Keine Daten für den gewählten Zeitraum.</p>';
    return;
  }
  const sized = calcBarWidths(rows, metric, refValue);
  container.innerHTML = sized
    .map((row) => {
      const sub =
        row.sublabel != null
          ? `<small>${row.sublabel}</small>`
          : row.kind === "child"
            ? `<small>${row.parent || ""}</small>`
            : "";
      const labelClass = row.kind === "child" ? " stats-bar-label is-nested" : " stats-bar-label";
      return `<div class="stats-bar-row dense">
        <span class="${labelClass.trim()}">${row.label}${sub}</span>
        <div class="stats-bar-track">
          <div class="stats-bar-fill ${fillClass}${fillExtra}" style="width:${row.width}%"></div>
        </div>
        <span class="stats-bar-value">${formatPerfValue(metric, row.value)}</span>
      </div>`;
    })
    .join("");
}

function renderPerfTable(mount, rows, colLabel, metric) {
  if (!mount) return;
  const meta = PERF_METRIC_META[metric];
  if (!rows.length) {
    mount.innerHTML = "";
    return;
  }
  const body = rows
    .map((row) => {
      const cls = row.kind === "parent" ? "is-area" : row.kind === "child" ? "is-product" : "";
      return `<tr class="${cls}"><td>${row.label}</td><td class="num">${formatPerfValue(metric, row.value)}</td></tr>`;
    })
    .join("");
  mount.innerHTML = `<div class="stats-perf-table-wrap"><table class="stats-perf-table"><thead><tr><th>${colLabel}</th><th class="num">${meta.column}</th></tr></thead><tbody>${body}</tbody></table></div>`;
}

function renderSimpleDimensionFold(segment, metric, period, view) {
  const fold = segment.querySelector(`[data-perf-view="${view}"]`);
  if (!fold) return;
  const rows = getFlatRows(metric, period, view);
  const colLabel = PERF_DIM_LABELS[view] || view;
  const refText = segment.querySelector(".stats-perf-consolidated-value")?.textContent;
  const refValue = parsePerfSummaryValue(metric, refText);
  renderPerfBarChart(fold.querySelector(".stats-perf-viz"), rows, metric, { refValue });
  renderPerfTable(fold.querySelector(".stats-perf-table-mount"), rows, colLabel, metric);
}

function buildComboFilterHtml(metric, period, primary, selectedKeys) {
  const keys = getDimensionKeys(metric, period, primary);
  if (!keys.length) return "<p class=\"stats-perf-empty\">Keine Filter verfügbar.</p>";
  return `<fieldset class="stats-perf-combo-filters"><legend>Einträge</legend><div class="stats-perf-combo-filter-grid">${keys
    .map(
      (key, idx) =>
        `<label><input type="checkbox" class="perf-combo-filter-cb" data-key="${key.replace(/"/g, "&quot;")}" ${selectedKeys[key] !== false ? "checked" : ""} /> ${key}</label>`,
    )
    .join("")}</div></fieldset>`;
}

function renderComboCard(segment, metric, period, combo, index) {
  const meta = PERF_METRIC_META[metric];
  const rows = getComboRows(metric, period, combo.primary, combo.secondary, combo.filters, combo.detailLevel);
  const colLabel = combo.secondary
    ? `${PERF_DIM_LABELS[combo.primary]} / ${PERF_DIM_LABELS[combo.secondary]}`
    : PERF_DIM_LABELS[combo.primary];
  const refText = segment.querySelector(".stats-perf-consolidated-value")?.textContent;
  const refValue = parsePerfSummaryValue(metric, refText);
  const card = document.createElement("article");
  card.className = "stats-perf-combo-card";
  card.dataset.comboIndex = String(index);
  const secondaryOptions = ["", "produkt", "gebiet", "mitarbeiter"]
    .filter((d) => d !== combo.primary)
    .map(
      (d) =>
        `<option value="${d}" ${combo.secondary === d ? "selected" : ""}>${d ? PERF_DIM_LABELS[d] : "Keine"}</option>`,
    )
    .join("");
  const primaryOptions = ["produkt", "gebiet", "mitarbeiter"]
    .map(
      (d) => `<option value="${d}" ${combo.primary === d ? "selected" : ""}>${PERF_DIM_LABELS[d]}</option>`,
    )
    .join("");
  card.innerHTML = `
    <div class="stats-perf-combo-card-head">
      <h5 class="stats-perf-combo-card-title">Kombination ${index + 1}</h5>
      <button type="button" class="stats-perf-combo-remove" aria-label="Kombination entfernen">Entfernen</button>
    </div>
    <div class="stats-perf-combo-config">
      <label class="stats-perf-combo-field">Name
        <input type="text" class="perf-combo-name" value="${(combo.name || comboLabel(combo.primary, combo.secondary)).replace(/"/g, "&quot;")}" maxlength="48" />
      </label>
      <label class="stats-perf-combo-field">Primär
        <select class="perf-combo-primary">${primaryOptions}</select>
      </label>
      <label class="stats-perf-combo-field">Sekundär
        <select class="perf-combo-secondary">${secondaryOptions}</select>
      </label>
      <label class="stats-perf-combo-field">Anzeige
        <select class="perf-combo-detail">
          <option value="summary" ${combo.detailLevel === "summary" ? "selected" : ""}>Nur Oberste Ebene</option>
          <option value="detail" ${combo.detailLevel === "detail" ? "selected" : ""}>Mit Unterebene</option>
        </select>
      </label>
    </div>
    ${buildComboFilterHtml(metric, period, combo.primary, combo.filters)}
    <div class="stats-perf-combo-preview">
      <h5>Vorschau</h5>
      <div class="stats-perf-viz perf-combo-viz"></div>
      <details class="stats-perf-subfold">
        <summary>Tabellenansicht</summary>
        <div class="stats-perf-subfold-body"><div class="stats-perf-table-mount"></div></div>
      </details>
    </div>`;
  renderPerfBarChart(card.querySelector(".perf-combo-viz"), rows, metric, {
    comboIndex: index,
    refValue,
  });
  renderPerfTable(card.querySelector(".stats-perf-table-mount"), rows, colLabel, metric);
  return card;
}

function renderComparePanel(segment, metric, period, combos) {
  const legend = segment.querySelector(".stats-perf-compare-legend");
  const ref = segment.querySelector(".stats-perf-compare-ref");
  const chart = segment.querySelector(".stats-perf-compare-chart");
  const refText = segment.querySelector(".stats-perf-consolidated-value")?.textContent || "—";
  const meta = PERF_METRIC_META[metric];
  if (ref) {
    ref.innerHTML = `<span>Referenz (konsolidiert):</span> <strong>${refText}</strong> <span class="stats-perf-compare-ref-hint">— ${meta.column}</span>`;
  }
  if (!legend || !chart) return;
  if (!combos.length) {
    legend.innerHTML = "";
    chart.innerHTML = '<p class="stats-perf-empty">Fügen Sie mindestens eine Kombination hinzu.</p>';
    return;
  }
  legend.innerHTML = combos
    .map((combo, idx) => {
      const name = combo.name || comboLabel(combo.primary, combo.secondary);
      return `<span class="stats-perf-compare-legend-item"><span class="stats-perf-compare-legend-swatch" style="background:${PERF_COMBO_COLORS[idx]}"></span>${name}</span>`;
    })
    .join("");
  const compareRows = [];
  combos.forEach((combo, idx) => {
    const rows = getComboRows(metric, period, combo.primary, combo.secondary, combo.filters, "summary");
    rows.forEach((row) => {
      compareRows.push({
        ...row,
        comboIndex: idx,
        sublabel: combo.name || comboLabel(combo.primary, combo.secondary),
      });
    });
  });
  const refValue = parsePerfSummaryValue(metric, refText);
  renderPerfBarChart(chart, compareRows, metric, { refValue });
  chart.querySelectorAll(".stats-bar-fill").forEach((el, i) => {
    const comboIndex = compareRows[i]?.comboIndex ?? 0;
    el.className = `stats-bar-fill combo-${comboIndex}`;
    el.style.background = PERF_COMBO_COLORS[comboIndex];
  });
}

function defaultComboFilters(metric, period, primary) {
  const filters = {};
  getDimensionKeys(metric, period, primary).forEach((key) => {
    filters[key] = true;
  });
  return filters;
}

function refreshPerformanceSegment(segment) {
  const metric = segment.dataset.perfMetric;
  if (!metric) return;
  const period = getPerformancePeriod();
  let state = perfSegmentState.get(segment);
  if (!state) {
    state = {
      combos: [
        { primary: "gebiet", secondary: "produkt", detailLevel: "detail", filters: defaultComboFilters(metric, period, "gebiet") },
        { primary: "mitarbeiter", secondary: "produkt", detailLevel: "detail", filters: defaultComboFilters(metric, period, "mitarbeiter") },
      ],
    };
    perfSegmentState.set(segment, state);
  }
  state.combos.forEach((combo) => {
    const keys = getDimensionKeys(metric, period, combo.primary);
    keys.forEach((key) => {
      if (combo.filters[key] === undefined) combo.filters[key] = true;
    });
    Object.keys(combo.filters).forEach((key) => {
      if (!keys.includes(key)) delete combo.filters[key];
    });
  });
  ["produkt", "gebiet", "mitarbeiter"].forEach((view) => renderSimpleDimensionFold(segment, metric, period, view));
  const list = segment.querySelector(".stats-perf-combo-list");
  const addBtn = segment.querySelector(".stats-perf-combo-add");
  if (list) {
    list.innerHTML = "";
    state.combos.forEach((combo, idx) => list.appendChild(renderComboCard(segment, metric, period, combo, idx)));
  }
  if (addBtn) addBtn.disabled = state.combos.length >= PERF_MAX_COMBOS;
  renderComparePanel(segment, metric, period, state.combos);
}

function refreshAllPerformanceSegments() {
  document.querySelectorAll(".stats-perf-segment[data-perf-metric]").forEach(refreshPerformanceSegment);
}

function initPerformanceSegments() {
  const panel = document.getElementById("statsPanelPerformance");
  if (!panel) return;
  panel.addEventListener("click", (event) => {
    const addBtn = event.target.closest(".stats-perf-combo-add");
    const removeBtn = event.target.closest(".stats-perf-combo-remove");
    const segment = event.target.closest(".stats-perf-segment[data-perf-metric]");
    if (!segment) return;
    const state = perfSegmentState.get(segment);
    if (!state) return;
    if (addBtn) {
      if (state.combos.length >= PERF_MAX_COMBOS) return;
      const metric = segment.dataset.perfMetric;
      const period = getPerformancePeriod();
      const primary = "produkt";
      state.combos.push({
        primary,
        secondary: "",
        detailLevel: "summary",
        filters: defaultComboFilters(metric, period, primary),
        name: "",
      });
      refreshPerformanceSegment(segment);
      return;
    }
    if (removeBtn) {
      const card = removeBtn.closest(".stats-perf-combo-card");
      const idx = Number(card?.dataset.comboIndex);
      if (!Number.isFinite(idx)) return;
      state.combos.splice(idx, 1);
      refreshPerformanceSegment(segment);
    }
  });
  panel.addEventListener("change", (event) => {
    const segment = event.target.closest(".stats-perf-segment[data-perf-metric]");
    if (!segment) return;
    const state = perfSegmentState.get(segment);
    if (!state) return;
    const card = event.target.closest(".stats-perf-combo-card");
    if (!card) return;
    const idx = Number(card.dataset.comboIndex);
    const combo = state.combos[idx];
    if (!combo) return;
    const metric = segment.dataset.perfMetric;
    const period = getPerformancePeriod();
    if (event.target.classList.contains("perf-combo-primary")) {
      combo.primary = event.target.value;
      combo.filters = defaultComboFilters(metric, period, combo.primary);
      if (combo.secondary === combo.primary) combo.secondary = "";
    }
    if (event.target.classList.contains("perf-combo-secondary")) {
      combo.secondary = event.target.value;
    }
    if (event.target.classList.contains("perf-combo-detail")) {
      combo.detailLevel = event.target.value;
    }
    if (event.target.classList.contains("perf-combo-name")) {
      combo.name = event.target.value;
    }
    if (event.target.classList.contains("perf-combo-filter-cb")) {
      const key = event.target.dataset.key;
      if (key) combo.filters[key] = event.target.checked;
    }
    refreshPerformanceSegment(segment);
  });
  panel.addEventListener("input", (event) => {
    if (!event.target.classList.contains("perf-combo-name")) return;
    const segment = event.target.closest(".stats-perf-segment[data-perf-metric]");
    const state = segment && perfSegmentState.get(segment);
    const card = event.target.closest(".stats-perf-combo-card");
    if (!state || !card) return;
    const combo = state.combos[Number(card.dataset.comboIndex)];
    if (combo) combo.name = event.target.value;
    refreshPerformanceSegment(segment);
  });
  refreshAllPerformanceSegments();
}

const PERF_SUMMARY_BY_PERIOD = {
  gesamt: { conversion: "32,4%", complaints: "2,1%", investment: "284 €" },
