function syncPerformanceSummaryKpis() {
  const select = document.getElementById("statsPerformancePeriod");
  const period = select?.value || "gesamt";
  const data = PERF_SUMMARY_BY_PERIOD[period] || PERF_SUMMARY_BY_PERIOD.gesamt;
  const conversionEl = document.getElementById("perfKpiConversion");
  const complaintsEl = document.getElementById("perfKpiComplaints");
  const investmentEl = document.getElementById("perfKpiInvestment");
  const consolidatedConversionEl = document.getElementById("perfConsolidatedConversion");
  const consolidatedComplaintsEl = document.getElementById("perfConsolidatedComplaints");
  const consolidatedInvestmentEl = document.getElementById("perfConsolidatedInvestment");
