function getComboRows(metric, period, primary, secondary, selectedKeys, detailLevel) {
  const dim = getPerfMetricData(metric, period)?.[primary];
  if (!dim?.flat) return [];
  const keys = Object.keys(dim.flat).filter((key) => selectedKeys[key] !== false);
  if (!secondary) {
    return keys.map((label) => ({ label, value: dim.flat[label], kind: "flat" }));
  }
  const rows = [];
  keys.forEach((parent) => {
    rows.push({ label: parent, value: dim.flat[parent], kind: "parent" });
    if (detailLevel === "detail" && dim.nested?.[parent]) {
      Object.entries(dim.nested[parent]).forEach(([child, value]) => {
        rows.push({ label: child, value, kind: "child", parent });
      });
    }
  });
  return rows;
}

function comboLabel(primary, secondary) {
  if (!secondary) return PERF_DIM_LABELS[primary] || primary;
  return `${PERF_DIM_LABELS[primary] || primary} × ${PERF_DIM_LABELS[secondary] || secondary}`;
}

input.new_string:
function getPerfHierarchy(metric, period) {
  const bucket = PERF_HIERARCHY_PERIOD[period];
  if (!bucket) return null;
  return bucket[metric] || null;
}

function getGebietKeys(metric, period) {
  const tree = getPerfHierarchy(metric, period);
  return tree ? Object.keys(tree) : [];
}

function defaultGebietFilters(metric, period) {
  const filters = {};
  getGebietKeys(metric, period).forEach((key) => {
    filters[key] = true;
  });
  return filters;
}

function normalizePerfCombo(combo, metric, period) {
  if (combo.level && combo.filters?.gebiet) return combo;
  const gebietFilters =
    combo.filters && !combo.filters.gebiet
      ? { gebiet: { ...combo.filters } }
      : { gebiet: defaultGebietFilters(metric, period) };
  let level = "gebiet";
  if (combo.primary === "gebiet" && combo.secondary === "produkt") level = "gebiet-produkt";
  else if (combo.primary === "gebiet" && combo.secondary === "mitarbeiter") level = "gebiet-mitarbeiter";
  else if (combo.primary === "mitarbeiter" || combo.secondary === "produkt") level = "gebiet-mitarbeiter-produkt";
  else if (combo.primary === "gebiet") level = combo.secondary ? "gebiet-mitarbeiter" : "gebiet";
  return {
    level,
    detailLevel: combo.detailLevel || "detail",
    filters: gebietFilters,
    name: combo.name || "",
  };
}

function hierarchyLevelLabel(level) {
  return PERF_HIERARCHY_LEVELS[level]?.short || level;
}

function getHierarchyRows(metric, period, level, gebietFilters, detailLevel) {
  const tree = getPerfHierarchy(metric, period);
  if (!tree) return [];
  const rows = [];
  const showChildren = detailLevel === "detail";

  Object.entries(tree).forEach(([gebiet, node]) => {
    if (gebietFilters[gebiet] === false) return;

    rows.push({
      label: gebiet,
      value: node.value,
      kind: "gebiet",
      depth: 0,
      path: gebiet,
    });

    if (level === "gebiet" || !showChildren) return;

    if (level === "gebiet-produkt") {
      Object.entries(node.produkt || {}).forEach(([produkt, value]) => {
        rows.push({
          label: produkt,
          value,
          kind: "produkt",
          depth: 1,
          parent: gebiet,
          path: `${gebiet} · ${produkt}`,
        });
      });
      return;
    }

    Object.entries(node.mitarbeiter || {}).forEach(([mitarbeiter, maNode]) => {
      rows.push({
        label: mitarbeiter,
        value: maNode.value,
        kind: "mitarbeiter",
        depth: 1,
        parent: gebiet,
        path: `${gebiet} · ${mitarbeiter}`,
      });

      if (level === "gebiet-mitarbeiter-produkt" && showChildren && maNode.produkt) {
        Object.entries(maNode.produkt).forEach(([produkt, value]) => {
          rows.push({
            label: produkt,
            value,
            kind: "produkt",
            depth: 2,
            parent: mitarbeiter,
            gebiet,
            path: `${gebiet} · ${mitarbeiter} · ${produkt}`,
          });
        });
      }
    });
  });

  return rows;
}

function hierarchyTableHeader(level) {
  if (level === "gebiet") return "Gebiet";
  if (level === "gebiet-mitarbeiter") return "Gebiet / Mitarbeiter";
  if (level === "gebiet-mitarbeiter-produkt") return "Gebiet / Mitarbeiter / Produkt";
  if (level === "gebiet-produkt") return "Gebiet / Produkt";
  return "Hierarchie";
}

