const MANUAL_LEAD_STATUSES = ["Neu", "In Bearbeitung", "Gewonnen", "Geschlossen"];
const SYSTEM_LEAD_STATUSES = [
  "Reklamation wird geprüft",
  "Reklamation abgelehnt - geschlossen",
  "Reklamation erfolgreich - geschlossen",
];

function isSystemLeadStatus(status) {
  return SYSTEM_LEAD_STATUSES.includes((status || "").trim());
}

function getStatusBadgeClass(status) {
  const value = (status || "").trim();
  if (value === "In Bearbeitung") return "progress";
  if (value === "Gewonnen") return "won";
  if (value === "Geschlossen") return "done";
  if (value === "Reklamation wird geprüft") return "reklamation-pending";
  if (value === "Reklamation abgelehnt - geschlossen") return "reklamation-rejected";
  if (value === "Reklamation erfolgreich - geschlossen") return "reklamation-success";
  return "new";
}

function renderLeadDetailStatusMarkup(status) {
  const value = (status || "").trim();
