}

function syncLeadDetailStatusControl(row) {
  const statusControl = document.querySelector(".detail-control-status");
  const readonlyWrap = document.getElementById("detailStatusReadonly");
  const readonlyBadge = document.getElementById("detailStatusReadonlyBadge");
  const systemHint = document.getElementById("detailStatusSystemHint");
  const status = (row?.dataset.status || getCellValue(row, "status") || "").trim();

  if (isSystemLeadStatus(status)) {
    statusControl?.classList.add("is-system-locked");
    if (readonlyWrap) readonlyWrap.hidden = false;
    if (readonlyBadge) {
      readonlyBadge.className = `status ${getStatusBadgeClass(status)}`;
      readonlyBadge.textContent = status;
    }
    if (systemHint) systemHint.hidden = false;
    if (detailStatusSelect) detailStatusSelect.disabled = true;
  } else {
    statusControl?.classList.remove("is-system-locked");
    if (readonlyWrap) readonlyWrap.hidden = true;
    if (systemHint) systemHint.hidden = true;
    if (detailStatusSelect) {
      detailStatusSelect.disabled = false;
      setSelectValue("detailStatusSelect", status);
    }
  }
}

