function defaultComboFilters() {
  return { gebiet: "", mitarbeiter: "" };
}

function normalizeComboFilters(combo, metric, period) {
  if (!combo.filters) combo.filters = defaultComboFilters();
  if (combo.filters && typeof combo.filters.gebiet === "object") {
    const keys = getGebietKeys(metric, period);
    const active = keys.filter((k) => combo.filters.gebiet[k] !== false);
    combo.filters = {
      gebiet: active.length === 1 ? active[0] : "",
      mitarbeiter: combo.filters.mitarbeiter || "",
    };
  }
  if (combo.filters.gebiet == null) combo.filters.gebiet = "";
  if (combo.filters.mitarbeiter == null) combo.filters.mitarbeiter = "";
  const gebiet = String(combo.filters.gebiet || "").trim();
  const mitarbeiter = String(combo.filters.mitarbeiter || "").trim();
  if (gebiet) {
    const allowed = getMitarbeiterKeysForGebiet(metric, period, gebiet);
    if (mitarbeiter && !allowed.includes(mitarbeiter)) {
      combo.filters.mitarbeiter = "";
    }
  }
  return combo.filters;
}

function getMitarbeiterKeysForGebiet(metric, period, gebiet) {
  const tree = getPerfHierarchy(metric, period);
  if (!gebiet || !tree?.[gebiet]?.mitarbeiter) return [];
  return Object.keys(tree[gebiet].mitarbeiter).sort((a, b) => a.localeCompare(b, "de"));
}

function getAllAssignableMitarbeiter(metric, period) {
  const tree = getPerfHierarchy(metric, period);
  const names = new Set();
  Object.values(tree || {}).forEach((node) => {
    Object.keys(node.mitarbeiter || {}).forEach((name) => names.add(name));
  });
  return Array.from(names).sort((a, b) => a.localeCompare(b, "de"));
}

function gebietFiltersFromSelection(selectedGebiet, metric, period) {
  const keys = getGebietKeys(metric, period);
  const filters = {};
  keys.forEach((key) => {
    filters[key] = selectedGebiet ? key === selectedGebiet : true;
  });
  return filters;
}

function getEmployeeProductRows(metric, period, mitarbeiter, detailLevel) {
  const dim = getPerfMetricData(metric, period)?.mitarbeiter;
  const value = dim?.flat?.[mitarbeiter];
  const nested = dim?.nested?.[mitarbeiter];
  if (value == null) return [];
  const showChildren = detailLevel === "detail";
  const rows = [
    {
      label: mitarbeiter,
      value,
      kind: "mitarbeiter",
      depth: 0,
      path: mitarbeiter,
    },
  ];
  if (showChildren && nested) {
    Object.entries(nested).forEach(([produkt, produktValue]) => {
      rows.push({
        label: produkt,
        value: produktValue,
        kind: "produkt",
        depth: 1,
        parent: mitarbeiter,
