}

function isFilterAllSelected(selected, allOptions) {
  return !selected.length || selected.length >= allOptions.length;
}

function multiSelectTriggerLabel(selected, allOptions, placeholder) {
  if (isFilterAllSelected(selected, allOptions)) return placeholder;
  if (selected.length === 1) return selected[0];
