function getProduktKeysForCombo(metric, period, gebiet, mitarbeiter) {
  const tree = getPerfHierarchy(metric, period);
  const g = String(gebiet || "").trim();
  const ma = String(mitarbeiter || "").trim();
  const products = new Set();
  if (!g && !ma) return getAllTenantProduktKeys(metric, period);

  if (g && ma) {
    const maNode = tree?.[g]?.mitarbeiter?.[ma];
    if (maNode?.produkt) {
      Object.keys(maNode.produkt).forEach((p) => products.add(p));
    }
    return Array.from(products).sort((a, b) => a.localeCompare(b, "de"));
  }

  if (g && tree?.[g]) {
    Object.keys(tree[g].produkt || {}).forEach((p) => products.add(p));
    Object.values(tree[g].mitarbeiter || {}).forEach((maNode) => {
      Object.keys(maNode.produkt || {}).forEach((p) => products.add(p));
    });
    return Array.from(products).sort((a, b) => a.localeCompare(b, "de"));
  }

  if (ma) {
    const nested = getPerfMetricData(metric, period)?.mitarbeiter?.nested?.[ma];
    if (nested) Object.keys(nested).forEach((p) => products.add(p));
    Object.entries(tree || {}).forEach(([, node]) => {
      const maNode = node.mitarbeiter?.[ma];
      if (maNode?.produkt) Object.keys(maNode.produkt).forEach((p) => products.add(p));
    });
    return Array.from(products).sort((a, b) => a.localeCompare(b, "de"));
  }

  return [];
}

