function wireNotificationCenter() {
  if (notificationCenterToggle?.dataset.notificationBound === "1") return;
  if (notificationCenterToggle) {
    notificationCenterToggle.dataset.notificationBound = "1";
  }

  notificationCenterToggle?.addEventListener("click", (e) => {
    e.stopPropagation();
    setNotificationPanelOpen(notificationCenterPanel.hidden);
  });

  document.addEventListener("click", (e) => {
    if (notificationWrap && !notificationWrap.contains(e.target)) {
      setNotificationPanelOpen(false);
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && notificationCenterPanel && !notificationCenterPanel.hidden) {
      setNotificationPanelOpen(false);
    }
  });

  notificationMarkAllReadCheckbox?.addEventListener("change", (e) => {
    e.stopPropagation();
    if (!notificationMarkAllReadCheckbox.checked) return;
    markAllNotificationsAsRead();
  });

  notificationList?.addEventListener("click", (e) => {
    const item = e.target.closest(".notification-item");
    if (!item || !notificationBelongsToCurrentUser(item)) return;

    const kind = item.dataset.notificationKind || "";

    if (kind === "client_won") {
      markNotificationItemAsRead(item);
      return;
    }

    const ref = resolveLeadRefFromNotificationButton(item);
    if (!ref) {
      markNotificationItemAsRead(item);
      return;
    }

    markLeadNotificationsAsRead(ref);

    const row = findLeadRowByAnfragenNummer(ref);
    if (!row) {
      window.alert(
        `Die Anfrage ${ref} ist in der aktuellen Übersicht nicht sichtbar (Filter oder entfernt).`,
      );
      return;
    }

    e.stopPropagation();
    setNotificationPanelOpen(false);
    setActiveMenu(menuMeineAnfragenBtn);
    openLeadDetailPage(row);
  });

  notificationShowAll?.addEventListener("click", (e) => {
    e.stopPropagation();
    if (notificationCenterFoot.hidden) return;
    setNotificationExpanded(!notificationCenterPanel.classList.contains("is-expanded"));
  });

  window.addEventListener("resize", () => {
    if (notificationCenterPanel && !notificationCenterPanel.hidden) {
      updateNotificationExpandFoot();
    }
  });
}

