function syncLeadComplaintLink(row) {
  const btn = document.getElementById("leadComplaintOpenBtn");
  const withdrawnHint = document.getElementById("leadComplaintWithdrawnHint");
  const slotStatus = document.getElementById("leadComplaintSlotStatus");
  const slotPriority = document.getElementById("leadComplaintSlotPriority");

  function setWithdrawnHintVisible(visible) {
    if (!withdrawnHint) return;
    withdrawnHint.hidden = !visible;
  }

  if (!btn) return;
  if (!row) {
    btn.hidden = false;
    btn.textContent = "Anfrage reklamieren";
    btn.dataset.complaintMode = "submit";
    btn.setAttribute("aria-label", "Anfrage reklamieren");
    setWithdrawnHintVisible(false);
    placeLeadComplaintButton(slotPriority);
    return;
  }
  const status = (row.dataset.status || getCellValue(row, "status") || "").trim();
  if (isComplaintPendingStatus(status)) {
    btn.hidden = false;
    btn.textContent = "Reklamation zurückziehen";
    btn.dataset.complaintMode = "withdraw";
    btn.setAttribute("aria-label", "Reklamation zurückziehen");
    setWithdrawnHintVisible(false);
    placeLeadComplaintButton(slotStatus);
    return;
  }
  if (hasWithdrawnComplaint(row)) {
    btn.hidden = true;
    setWithdrawnHintVisible(true);
    placeLeadComplaintButton(slotPriority);
    return;
  }
  setWithdrawnHintVisible(false);
  if (isFinalReklamationStatus(status) || isComplaintSubmissionBlocked(status, row)) {
    btn.hidden = true;
    placeLeadComplaintButton(slotPriority);
    return;
  }
  btn.hidden = false;
  btn.textContent = "Anfrage reklamieren";
  btn.dataset.complaintMode = "submit";
  btn.setAttribute("aria-label", "Anfrage reklamieren");
  placeLeadComplaintButton(slotPriority);
}

